/**
 * Populate the given owner's transient {@code householdMemberCount} with the current number of
 * owners that share its {@code householdId}, so the derived {@code membershipTier} reflects the
 * household size (3 or more members earns {@code GOLD}). Owners without a household id are left
 * at a count of zero.
 */
private void populateHouseholdMemberCount(Owner owner) {
    if (owner == null) {
        return;
    }
    owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
}

/**
 * Count the owners that belong to the household identified by the given id. Returns 0 when the
 * id is {@code null}, so owners that do not share a household never reach the {@code GOLD}
 * threshold.
 */
private int countHouseholdMembers(String householdId) {
    if (householdId == null) {
        return 0;
    }
    return (int) ownerRepository.findAll().stream()
        .filter(owner -> householdId.equals(owner.getHouseholdId()))
        .count();
}

